import axios from 'axios';
import { readFile } from 'node:fs/promises';

const invokeUrl = "https://integrate.api.nvidia.com/v1/chat/completions";
const stream = <%- request.stream %>;

const headers = {
  "Authorization": "Bearer $NVIDIA_API_KEY",
  "Accept": stream ? "text/event-stream" : "application/json"
};
<% content = "Answer the spoken query about the image.<img src=\"data:image/png;base64,${imageB64}\" /><audio src=\"data:audio/wav;base64,${audioB64}\" />" %>
Promise.all([
  readFile("image.png"),
  readFile("audio.wav")
])
  .then(([imageData, audioData]) => {
    const imageB64 = Buffer.from(imageData).toString('base64');
    const audioB64 = Buffer.from(audioData).toString('base64');

    if (imageB64.length + audioB64.length > 180_000) {
      throw new Error("To upload larger images and/or audios, use the assets API (see docs)");
    }

    const payload = {
      "model": `<%- request.model %>`,
      "messages": [
        {
          "role": "user",
          "content": `<%- content %>`
        }
      ],
      "max_tokens": <%- request.max_tokens %>,
      "temperature": <%- request.temperature.toFixed(2) %>,
      "top_p": <%- request.top_p.toFixed(2) %>,
      "stream": stream
    };

    return axios.post(invokeUrl, payload, { headers: headers, responseType: stream ? 'stream' : 'json' });
  })
  .then(response => {
    if (stream) {
      response.data.on('data', (chunk) => {
        console.log(chunk.toString());
      });
    } else {
      console.log(JSON.stringify(response.data));
    }
  })
  .catch(error => {
    console.error(error);
  });

import fetch from "node-fetch";

const invokeUrl = "https://ai.api.nvidia.com/v1/genai/microsoft/trellis"

const headers = {
    "Authorization": "Bearer $NVIDIA_API_KEY",
    "Accept": "application/json",
}

const payload = {
    <% if (request.mode === "text") { %>"prompt": <%- JSON.stringify(request.prompt).replaceAll('\'', '\'\\\'\'') %>,<% } else { %>"image": "<%- request.image %>",<% } %>
    "slat_cfg_scale": <%- request.slat_cfg_scale %>,
    "ss_cfg_scale": <%- request.ss_cfg_scale %>,
    "slat_sampling_steps": <%- request.slat_sampling_steps %>,
    "ss_sampling_steps": <%- request.ss_sampling_steps %>,
    "seed": <%- request.seed %>
}

let response = await fetch(invokeUrl, {
    method: "post",
    body: JSON.stringify(payload),
    headers: { "Content-Type": "application/json", ...headers }
});

if (response.status != 200) {
  let errBody = await (await response.blob()).text()
  throw "invocation failed with status " + response.status + " " + errBody
}
let response_body = await response.json()
console.log(JSON.stringify(response_body))

