import axios from 'axios';
import { readFile } from 'node:fs/promises';

const invokeUrl = "https://integrate.api.nvidia.com/v1/chat/completions";
const stream = <%- request.stream %>;
<%
  const messages = JSON.stringify(request.messages)
  const firstContent = typeof request.messages?.[0]?.content === "string" ? request.messages[0].content : "";
  const hasImage = /<img[^>]*\/?>/i.test(firstContent);
  const imageCount = (firstContent.match(/<img[^>]*\/?>/gi) || []).length;
  let rendered_messages;

  if (hasImage) {
    const tagRegex = /<img\b[^>]*\/?>/gi;
    const contentParts = [];
    let imgIdx = 0;
    let lastIdx = 0;
    let tagMatch;
    while ((tagMatch = tagRegex.exec(firstContent)) !== null) {
      const leadingText = firstContent.slice(lastIdx, tagMatch.index);
      if (leadingText.trim()) {
        contentParts.push({ type: "text", text: leadingText });
      }
      contentParts.push({
        type: "image_url",
        image_url: { url: `__IMAGE_${imgIdx}__` }
      });
      imgIdx += 1;
      lastIdx = tagRegex.lastIndex;
    }
    const trailingText = firstContent.slice(lastIdx);
    if (trailingText.trim()) {
      contentParts.push({ type: "text", text: trailingText });
    }
    let renderedContent = JSON.stringify(contentParts, null, 8);
    for (let i = 0; i < imgIdx; i++) {
      renderedContent = renderedContent.replace(
        `"__IMAGE_${i}__"`,
        `\`data:image/png;base64,\${image_${i + 1}_b64}\``,
      );
    }

    rendered_messages = `[
      {
        "role": "user",
        "content": ${renderedContent}
      }
    ]`;
  } else {
    rendered_messages = messages
  }
%>
const headers = {
  "Authorization": "Bearer $NVIDIA_API_KEY",
  "Accept": stream ? "text/event-stream" : "application/json"
};
<% if (hasImage) { %>
Promise.all([<% for (let i = 1; i <= imageCount; i++) { %>readFile("image_<%- i %>.png"), <% } %>])
  .then((imageBuffers) => {
    <% for (let i = 1; i <= imageCount; i++) { %>const image_<%- i %>_b64 = Buffer.from(imageBuffers[<%- i - 1 %>]).toString('base64');
    <% } %>

    const payload = {
      "model": `<%- request.model %>`,
      "messages": <%- rendered_messages %>,
