    accept_header='Accept: text/event-stream'
else
    accept_header='Accept: application/json'
fi
<%
  const messages = JSON.stringify(request.messages)
  const firstContent = typeof request.messages?.[0]?.content === "string" ? request.messages[0].content : "";
  const hasImage = /<img[^>]*\/?>/i.test(firstContent);
  const imageCount = (firstContent.match(/<img[^>]*\/?>/gi) || []).length;
  let rendered_messages;

  if (hasImage) {
    const tagRegex = /<img\b[^>]*\/?>/gi;
    const contentParts = [];
    let imgIdx = 0;
    let lastIdx = 0;
    let tagMatch;
    while ((tagMatch = tagRegex.exec(firstContent)) !== null) {
      const leadingText = firstContent.slice(lastIdx, tagMatch.index);
      if (leadingText.trim()) {
        contentParts.push({ type: "text", text: leadingText });
      }
      contentParts.push({
        type: "image_url",
        image_url: { url: `data:image/png;base64,\${image_${imgIdx + 1}_b64}` }
      });
      imgIdx += 1;
      lastIdx = tagRegex.lastIndex;
    }
    const trailingText = firstContent.slice(lastIdx);
    if (trailingText.trim()) {
      contentParts.push({ type: "text", text: trailingText });
    }
    rendered_messages = JSON.stringify([{ role: "user", content: contentParts }], null, 4);
  } else {
    rendered_messages = messages
  }
%>
