    console.log(
      "Usage: node test.js <reference_image> <test_image> <output_dir>"
    );
    process.exit(1);
  }

  const assetId1 = await uploadAsset(process.argv[2], "Reference Image");
  const assetId2 = await uploadAsset(process.argv[3], "Test Image");

  const inputs = {
    reference_image: `${assetId1}`,
    test_image: `${assetId2}`,
  };
  const assetList = `${assetId1} , ${assetId2}`;

  const response = await fetch(nvai_url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "NVCF-INPUT-ASSET-REFERENCES": assetList,
      "NVCF-FUNCTION-ASSET-IDS": assetList,
      Authorization: header_auth,
    },
    body: JSON.stringify(inputs),
  });

  const buffer = await response.arrayBuffer();
  fs.writeFileSync(`${process.argv[4]}.zip`, Buffer.from(buffer));

  // Unzip the response synchronously
  await decompress(`${process.argv[4]}.zip`, process.argv[4]);

  // Log the output directory and its contents
  console.log(`Response saved to ${process.argv[4]}`);
  console.log(fs.readdirSync(process.argv[4]));
})();

