import axios from 'axios';
import { readFile } from 'node:fs/promises';

const invokeUrl = "https://integrate.api.nvidia.com/v1/chat/completions";
const stream = <%- request.stream %>;

const headers = {
  "Authorization": "Bearer $NVIDIA_API_KEY",
  "Accept": stream ? "text/event-stream" : "application/json"
};
<%
  const messages = JSON.stringify(request.messages)
  const hasImg = /<img[^>]*\/?>/i.test(messages);
  let rendered_messages;

  if (hasImg) {
    let baseText = request.messages[0].content.replace(/<img[^>]*\/>\s*/i, '').trim();
    baseText = baseText.replace(/"/g, '\\"');
    const content = `${baseText} <img src="data:image/png;base64,\${image_b64}" />`;

    rendered_messages = `[
      {
        "role": "user",
        "content": \`${content}\`
      }
    ]`;
  } else {
    rendered_messages = messages
  }
%>
<% if (hasImg) { %>
readFile("image.png")
  .then(data => {
    const image_b64 = Buffer.from(data).toString('base64');

    const payload = {
      "model": `<%- request.model %>`,
      "messages": <%- rendered_messages %>,
      "max_tokens": <%- request.max_tokens %>,
      "temperature": <%- request.temperature.toFixed(2) %>,
      "top_p": <%- request.top_p.toFixed(2) %>,
      "stream": stream,
      <%- request.chat_template_kwargs ? '"chat_template_kwargs": ' + JSON.stringify(request.chat_template_kwargs) + ',' : '' %>
      <% if (request.tools) { %>"tools": <%- JSON.stringify(request.tools) %>,<% } %>
      <% if (request.tool_choice) { %>"tool_choice": <%- JSON.stringify(request.tool_choice) %><% } %>
    };

    return axios.post(invokeUrl, payload, { headers: headers, responseType: stream ? 'stream' : 'json' });
  })
<% } else { %>
const payload = {
  "model": "<%- request.model %>",
  "messages": <%- rendered_messages %>,
  "max_tokens": <%- request.max_tokens %>,
  "temperature": <%- request.temperature.toFixed(2) %>,
  "top_p": <%- request.top_p.toFixed(2) %>,
  "stream": stream,
  <%- request.chat_template_kwargs ? '"chat_template_kwargs": ' + JSON.stringify(request.chat_template_kwargs) + ',' : '' %>
  <% if (request.tools) { %>"tools": <%- JSON.stringify(request.tools) %>,<% } %>
  <% if (request.tool_choice) { %>"tool_choice": <%- JSON.stringify(request.tool_choice) %><% } %>
};

Promise.resolve(
  axios.post(invokeUrl, payload, {
    headers: headers,
    responseType: stream ? 'stream' : 'json'
  })
)
<% } %>
  .then(response => {
    if (stream) {
      response.data.on('data', (chunk) => {
        console.log(chunk.toString());
      });
    } else {
      console.log(JSON.stringify(response.data));
    }
  })
  .catch(error => {
    console.error(error);
  });

