package main

import (
    "bytes"
    "fmt"
    "io"
    "net/http"
    "os"
    "time"
)

func main() {
    // Get or request the NGC_API_KEY
    nvcfRunKey := os.Getenv("NGC_API_KEY")
    if len(nvcfRunKey) == 0 {
        nvcfRunKey = "$NVIDIA_API_KEY"
    }
    // Define constants and payload
    invokeURL := "https://climate.api.nvidia.com/v1/nvidia/corrdiff"
    outputFile := "output.zip"
    payload := `{"input_id": <%- request.input_id %>, "samples": <%- request.samples %>, "steps": <%- request.steps %>}`
    fmt.Println("Payload:", payload)

    // Make initial request
    fmt.Printf("%s Making inference request\n", time.Now())
    req, err := http.NewRequest("POST", invokeURL, bytes.NewBuffer([]byte(payload)))
    if err != nil {
        fmt.Println("Error creating request:", err)
        return
    }
    req.Header.Set("Content-Type", "application/json")
    req.Header.Set("Authorization", "Bearer "+nvcfRunKey)
    req.Header.Set("NVCF-POLL-SECONDS", "5")

    client := &http.Client{}
    resp, err := client.Do(req)
    if err != nil {
        fmt.Println("Request error:", err)
        return
    }
    defer resp.Body.Close()

    // Check HTTP status code
    if resp.StatusCode != 202 {
        fmt.Printf("Unexpected HTTP status: %d\n", resp.StatusCode)
        return
    }

    // Get NVCF-ReqID header from response
    reqID := resp.Header.Get("nvcf-reqid")
    fmt.Printf("Request ID: %s\n", reqID)

    // Poll the status endpoint
    statusURL := fmt.Sprintf("https://api.nvcf.nvidia.com/v2/nvcf/pexec/status/%s", reqID)
    fmt.Printf("%s Polling job %s\n", time.Now(), reqID)

    for {
        statusReq, err := http.NewRequest("GET", statusURL, nil)
        statusReq.Header.Set("Content-Type", "application/json")
        statusReq.Header.Set("Authorization", "Bearer "+nvcfRunKey)
        statusReq.Header.Set("NVCF-POLL-SECONDS", "5")

        statusResp, err := client.Do(statusReq)
        if err != nil {
            fmt.Println("Status request error:", err)
            return
        }
        defer statusResp.Body.Close()

        // Check status response HTTP code
        if statusResp.StatusCode == 200 {
            // Save response to file
            file, err := os.Create(outputFile)
            defer file.Close()
            _, err = io.Copy(file, statusResp.Body)
            if err != nil {
                fmt.Println("Error saving response to file:", err)
                return
            }
            fmt.Println("Saved response to file")
            break
        } else if statusResp.StatusCode == 302 {
            // Download large asset from redirected location
            assetURL := statusResp.Header.Get("Location")
            fmt.Println("Downloading large asset")
            assetResp, err := client.Get(assetURL)
            if err != nil {
                fmt.Println("Error downloading asset:", err)
                return
            }
            defer assetResp.Body.Close()
            file, err := os.Create(outputFile)
            defer file.Close()
            _, err = io.Copy(file, assetResp.Body)
            if err != nil {
                fmt.Println("Error saving asset to file:", err)
                return
            }
            break
        } else if statusResp.StatusCode != 202 {
            fmt.Printf("Unexpected HTTP status: %d\n", statusResp.StatusCode)
            respBody, _ := io.ReadAll(statusResp.Body)
            fmt.Println("Response:", string(respBody))
            return
        }

        fmt.Printf("%s Job still running, status %d\n", time.Now(), statusResp.StatusCode)
        time.Sleep(3 * time.Second)
    }
}
